const CAUSES = {
 "Unclear requirements": 42,
 "Late scope changes": 25,
 "Missing users in reviews": 14,
 "Tool problems": 6,
 "Staff turnover": 5,
 "Unclear templates": 4,
 "Other": 4
};
function pareto(counts, threshold) {
  var keys = Object.keys(counts).sort(function (a, b) { return counts[b] - counts[a] || (a < b ? -1 : a > b ? 1 : 0); });
  var total = keys.reduce(function (s, k) { return s + counts[k]; }, 0);
  var out = [], cum = 0;
  for (var i = 0; i < keys.length && total > 0; i++) {
    out.push(keys[i]); cum += counts[keys[i]];
    if (cum * 100 >= threshold * total) break;
  }
  return out;
}
